const requester = input.requester;
const validProject = /^[a-z0-9][a-z0-9-]{0,63}$/.test(projectId);
const validRequester = requester && requester.source === 'open-webui' && typeof requester.subject === 'string' && /^owui-sha256:[0-9a-f]{64}$/.test(requester.subject);
const validRequestId = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(requestId);
