function safeFailure(message) {
  const normalized = message.toLowerCase();
  if (normalized.includes('max iterations')) return 'PatchPony hat das Recherchelimit erreicht. Bitte grenze die Frage weiter ein und versuche es erneut.';
  if (normalized.includes('timeout') || normalized.includes('timed out')) return 'PatchPony hat nicht rechtzeitig geantwortet. Bitte versuche es erneut.';
  if (normalized.includes('abort') || normalized.includes('cancel')) return 'Die PatchPony-Anfrage wurde abgebrochen. Bitte stelle die Frage erneut, wenn du fortfahren möchtest.';
  if (normalized.includes('rate limit') || normalized.includes('429')) return 'PatchPony ist gerade ausgelastet. Bitte warte kurz und versuche es erneut.';
  return 'PatchPony konnte diese Anfrage derzeit nicht verarbeiten. Bitte versuche es später erneut.';
}
