const answer = typeof $json.output === 'string' && $json.output.trim() ? $json.output.trim() : 'PatchPony konnte keine Antwort erzeugen.';
const allowedTools = new Set(['runtime.status', 'runtime.validate_correlation', 'source.search', 'source.read']);
const toolCalls = [];
const sources = [];
const seenTools = new Set();
const seenSources = new Set();
const safeProject = /^[a-z0-9][a-z0-9-]{0,63}$/;
const safePath = /^[A-Za-z0-9._/@+:-]+(?:\/[A-Za-z0-9._/@+:-]+)*$/;

function addTool(value) {
  if (toolCalls.length < 6 && typeof value === 'string' && allowedTools.has(value) && !seenTools.has(value)) {
    seenTools.add(value);
    toolCalls.push(value);
  }
}
function addCitation(value) {
